  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C103", "C94", "C49", "C35", "C41", "C48", "C56", "C63", "C79", "C80", "C82"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C103", "C94", "C49", "C35", "C41", "C48", "C56"],
  "claims": [
    {
      "claim": "The query is a rifamycin ansamycin bearing a methylpiperazinyl hydrazone; the closest L4 analog rifapentine efficiently crossed Caco-2 and MDCK monolayers in both directions, supporting intestinal permeability for this scaffold.",
      "card_ids": ["C103", "C94"]
    },
    {
      "claim": "Rifamycin-class oral exposure records show measurable systemic exposure after oral dosing: rifabutin Cmax 188–600 ng/mL and AUC0-24 ~3053 ng·h/mL; rifamycin exposure AUC0-24 ~37–41 mg·h/L and Cmax ~8–9 mg/L; KRM-1648 dog AUC0-48 ~11 µg·h/mL. These are directionally consistent with oral absorption.",
      "card_ids": ["C35", "C41", "C48", "C49", "C56", "C63", "C79", "C80", "C82"]
    },
    {
      "claim": "Low-solubility records for rifaximin and unrelated molecules do not provide affirmative threshold-relevant evidence for F < 20% for the query; rifaximin's C3 fused-heterocycle differs from the query's hydrazone-piperazine and is not transferable as a negative.",
      "card_ids": ["C89", "C113", "C100", "C85"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C103", "C94"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself; all records are for analogs.",
    "No direct solubility or permeability measurement for the query itself; rifapentine permeability is the closest analog evidence.",
    "L3 exposure records lack matched IV comparators, so they cannot by themselves establish the F >= 20% threshold.",
    "Rifaximin low-solubility records are not transferable to the query's hydrazone-piperazine scaffold; no affirmative low-F evidence is present.",
    "The unfavorable physicochemical prior is not endpoint proof and is outweighed by analog permeability and exposure evidence."
  ],
  "decision_summary": "L4 adds rifapentine permeability evidence supporting intestinal absorption for the query's rifamycin-hydrazone scaffold, while low-solubility records for rifaximin and unrelated molecules do not provide affirmative F < 20% evidence. Combined with L3 rifamycin-class exposure records, the prediction remains high with moderate confidence; the decision is strengthened."
}

